 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page();page.goto('http://127.0.0.1:8000/');result=page.evaluate('''async()=>{const {answerStripSVG}=await import('./cbse-mcq-print.js');const {bubblePoint,scanResponsePhoto,responseGeometry}=await import('./cbse-mcq-scan.js');const geometry=responseGeometry(6,true,true,true),svg=answerStripSVG(6,0,true,true,true,true),img=new Image();img.src='data:image/svg+xml;base64,'+btoa(new XMLSerializer().serializeToString(svg));await img.decode();const c=document.createElement('canvas');c.width=geometry.width;c.height=geometry.height;const g=c.getContext('2d');g.drawImage(img,0,0);for(const [i,a]of [[1,1],[2,3],[3,1],[4,1],[5,2]]){const p=bubblePoint(i,a);g.fillStyle='#44318c';g.beginPath();g.arc(p.x,p.y,9,0,Math.PI*2);g.fill();}const gradient=g.createLinearGradient(0,0,c.width,0);gradient.addColorStop(0,'rgba(0,0,0,.60)');gradient.addColorStop(1,'rgba(0,0,0,.05)');g.fillStyle=gradient;g.fillRect(0,0,c.width,c.height);const photo=document.createElement('canvas');photo.width=c.height+150;photo.height=c.width+150;const ctx=photo.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,photo.width,photo.height);ctx.translate(c.height+50,50);ctx.rotate(Math.PI/2);ctx.drawImage(c,0,0);ctx.fillStyle='black';ctx.fillRect(-20,-20,3,3);return scanResponsePhoto(photo,6,{compact:true});}''');assert result['responses']==['','B','D','B','B','C'],result;b.close()
